svg.script:
function show_3e3d370b(evt, text) {
	var pos = (evt.target.getAttribute("y") < 1134) ? "bottom" : "top";
	var note = document.getElementById(pos + "_note_3e3d370b");
	note.textContent = text;
	note.setAttributeNS(null, "visibility", "visible");
	document.getElementById(pos + "_overlay_3e3d370b").setAttributeNS(null, "visibility", "visible");
}
function hide_3e3d370b(evt) {
	document.getElementById("top_note_3e3d370b").setAttributeNS(null, "visibility", "hidden");
	document.getElementById("top_overlay_3e3d370b").setAttributeNS(null, "visibility", "hidden");
	document.getElementById("bottom_note_3e3d370b").setAttributeNS(null, "visibility", "hidden");
	document.getElementById("bottom_overlay_3e3d370b").setAttributeNS(null, "visibility", "hidden");
}
